<?php
declare(strict_types=1);
if (!defined('_GNUBOARD_')) { http_response_code(403); exit; }
const NOA_LAB_ORIGIN='https://noastudio.ai.kr';
function lab_root():string { $path=dirname(G5_PATH).'/noa-ai-lab'; if(!is_dir($path)||is_link($path))throw new RuntimeException('private_storage_unavailable'); return $path; }
function lab_defaults():array {return ['revision'=>0,'configRevision'=>0,'jobs'=>[],'channels'=>[],'config'=>['generationEnabled'=>false,'textEnabled'=>false,'model'=>'gpt-5-mini','creativeRules'=>'','maxJobUsd'=>0,'dailyBudgetUsd'=>0,'oauthClientId'=>'','workerEnabled'=>true],'events'=>[],'nonces'=>[]];}
function lab_lock(callable $fn):mixed {
 $root=lab_root();$lock=fopen($root.'/state.lock','c+');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('storage_lock');
 try{$file=$root.'/state.json';$state=is_file($file)?json_decode((string)file_get_contents($file),true,512,JSON_THROW_ON_ERROR):lab_defaults();$result=$fn($state);$state['revision']++;$temp=tempnam($root,'.state-');if($temp===false)throw new RuntimeException('storage_write');chmod($temp,0600);$raw=json_encode($state,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(file_put_contents($temp,$raw)!==strlen($raw)||!rename($temp,$file))throw new RuntimeException('storage_write');return $result;}finally{flock($lock,LOCK_UN);fclose($lock);}
}
function lab_read():array { $lock=fopen(lab_root().'/state.lock','c+');if(!$lock||!flock($lock,LOCK_SH))throw new RuntimeException('storage_lock');try{$path=lab_root().'/state.json';return is_file($path)?json_decode((string)file_get_contents($path),true,512,JSON_THROW_ON_ERROR):lab_defaults();}finally{flock($lock,LOCK_UN);fclose($lock);} }
function lab_seal(array $value):string { $key=file_get_contents(lab_root().'/master.key');if(strlen($key)!==32)throw new RuntimeException('key_unavailable');$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt(json_encode($value,JSON_THROW_ON_ERROR),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag,'NOA-AI-LAB-v1');if($cipher===false)throw new RuntimeException('encryption_failed');return base64_encode($iv.$tag.$cipher); }
function lab_unseal(?string $sealed):array {if(!$sealed)return [];$raw=base64_decode($sealed,true);if($raw===false||strlen($raw)<28)throw new RuntimeException('invalid_secrets');$text=openssl_decrypt(substr($raw,28),'aes-256-gcm',file_get_contents(lab_root().'/master.key'),OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16),'NOA-AI-LAB-v1');if($text===false)throw new RuntimeException('invalid_secrets');return json_decode($text,true,512,JSON_THROW_ON_ERROR);}
function lab_event(array &$s,string $type,string $job='',string $actor='worker'):void {$s['events'][]=['at'=>gmdate('c'),'type'=>$type,'job'=>$job,'actor'=>$actor];$s['events']=array_slice($s['events'],-1000);}
function lab_id(string $id):string {if(!preg_match('/^[a-f0-9]{32}$/D',$id))throw new InvalidArgumentException('invalid_id');return $id;}
function lab_job_dir(string $id):string {return lab_root().'/jobs/'.lab_id($id);}
function lab_public_job(array $j):array { $out=array_intersect_key($j,array_flip(['id','trackKey','title','cast','genre','sourceRevision','state','revision','createdAt','updatedAt','analysis','selection','settings','promotion','outputs','metrics','error','attempts','inputReady','audioSha256','approvedAt','retryAt','costReservedUsd','rights','review','history','stems','creation','usage','mastering','masterOptions','type']));foreach($out['outputs']??[] as $i=>$o)$out['outputs'][$i]=array_intersect_key($o,array_flip(['format','duration','width','height','sha256','videoId','url','publishedAt','checks']));return $out;}
function lab_status():array {$s=lab_read();$secrets=lab_unseal($s['secrets']??null);$channels=[];foreach($s['channels'] as $id=>$c)$channels[]=['id'=>$id,'title'=>$c['title'],'autoEnabled'=>$c['autoEnabled']??false,'connectedAt'=>$c['connectedAt']];return ['configRevision'=>$s['configRevision']??0,'config'=>$s['config'],'configured'=>['fal'=>!empty($secrets['falKey']),'textAI'=>!empty($secrets['openaiKey']),'oauth'=>!empty($s['config']['oauthClientId'])&&!empty($secrets['oauthClientSecret'])],'channels'=>$channels,'jobs'=>array_map('lab_public_job',array_values($s['jobs'])),'events'=>array_slice($s['events'],-40),'worker'=>$s['worker']??null,'revision'=>$s['revision']];}
function lab_json(int $code,array $body):never {http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');echo json_encode($body,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function lab_admin():void {global $is_member,$is_admin;if(empty($is_member)||($is_admin??'')!=='super')lab_json(403,['error'=>'admin_required']);}
function lab_csrf():void {if(($_SERVER['HTTP_ORIGIN']??'')!==NOA_LAB_ORIGIN||empty($_SESSION['noa_lab_csrf'])||!hash_equals($_SESSION['noa_lab_csrf'],$_SERVER['HTTP_X_NOA_CSRF']??''))lab_json(403,['error'=>'request_verification_failed']);}
function lab_json_body(int $limit=262144):array {if(strtolower(trim(explode(';',$_SERVER['CONTENT_TYPE']??'')[0]))!=='application/json')lab_json(415,['error'=>'json_required']);$raw=file_get_contents('php://input',false,null,0,$limit+1);if($raw===false||strlen($raw)>$limit)lab_json(413,['error'=>'too_large']);$b=json_decode($raw,true);if(!is_array($b)||array_is_list($b))lab_json(400,['error'=>'invalid_json']);return $b;}
function lab_revision(array $job,array $body):void {if(!is_int($body['expectedRevision']??null)||$body['expectedRevision']!==$job['revision'])throw new DomainException('revision_conflict');}
function lab_touch(array &$j):void {$j['revision']++;$j['updatedAt']=gmdate('c');}
function lab_https(string $url,array $options=[]):array {
 $c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>30,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS]+$options);$raw=curl_exec($c);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);if($raw===false||$code<200||$code>=300)throw new RuntimeException('remote_request_failed');return json_decode($raw,true,512,JSON_THROW_ON_ERROR);
}
function lab_validate_selection(array $selection,float $duration):array {
 $a=$selection['start']??null;$b=$selection['end']??null;if(!is_numeric($a)||!is_numeric($b)||!is_finite((float)$a)||!is_finite((float)$b)||$a<0||$b<=$a||$b-$a>60.001||$b>$duration+.01)throw new InvalidArgumentException('invalid_range');return ['start'=>(float)$a,'end'=>(float)$b,'candidateId'=>(string)($selection['candidateId']??'manual')];
}
function lab_validate_settings(array $in,array $s):array {
 $mode=$in['mode']??'';$formats=$in['formats']??[];$posting=$in['posting']??'save';if(!in_array($mode,['cinematic','lipsync','audio'],true)||!is_array($formats)||!$formats||array_diff($formats,['landscape','shorts'])||count($formats)>2||!in_array($posting,['save','approval','schedule','auto'],true))throw new InvalidArgumentException('invalid_settings');
 if($mode==='audio')$posting='save';$channel=(string)($in['channelId']??'');if($posting!=='save'&&!isset($s['channels'][$channel]))throw new InvalidArgumentException('connect_channel_first');if(in_array($posting,['auto','schedule'],true)&&empty($s['channels'][$channel]['autoEnabled']))throw new DomainException('channel_auto_disabled');
 $publishAt=$in['publishAt']??null;if($posting==='schedule'){if(!is_string($publishAt)||($time=strtotime($publishAt))===false||$time<time()+900)throw new InvalidArgumentException('schedule_at_least_15_minutes_ahead');$publishAt=gmdate('c',$time);}else $publishAt=null;
 $turns=$in['vocalTurns']??[];if(!is_array($turns)||count($turns)>60)throw new InvalidArgumentException('invalid_vocal_turns');foreach($turns as $t){if(!is_array($t)||!in_array($t['cast']??'',['female','male','duet'],true)||!is_numeric($t['start']??null)||!is_numeric($t['end']??null)||$t['end']<=$t['start'])throw new InvalidArgumentException('invalid_vocal_turns');}
 return ['mode'=>$mode,'formats'=>array_values(array_unique($formats)),'posting'=>$posting,'channelId'=>$channel,'publishAt'=>$publishAt,'subtitles'=>($in['subtitles']??false)===true,'autoSelect'=>($in['autoSelect']??false)===true,'vocalTurns'=>$turns,'madeForKids'=>($in['madeForKids']??false)===true];
}
function lab_reserve_cost(array &$s,array &$j,bool $analysisOnly=false):void {
 if(empty($s['config']['generationEnabled']))throw new DomainException('generation_disabled');$secrets=lab_unseal($s['secrets']??null);if(empty($secrets['falKey'])||empty($secrets['openaiKey']))throw new DomainException('generation_keys_required');
 $length=$analysisOnly?0:$j['selection']['end']-$j['selection']['start'];$estimate=$j['settings']['mode']==='cinematic'?ceil($length/5)*5*.07:$length*.115*($j['cast']==='duet'?2:1);$estimate=round($estimate+0.25,2);
 if($estimate>(float)$s['config']['maxJobUsd'])throw new DomainException('job_budget_exceeded');$today=gmdate('Y-m-d');$reserved=(float)($s['ainoaUsage'][$today]??0);foreach($s['jobs'] as $other)if($other['id']!==$j['id']&&substr($other['costReservedAt']??'',0,10)===$today)$reserved+=(float)($other['costReservedUsd']??0);if($reserved+$estimate>(float)$s['config']['dailyBudgetUsd'])throw new DomainException('daily_budget_exceeded');$j['costReservedUsd']=$estimate;$j['costReservedAt']=gmdate('c');
}

function lab_deduplicate(array $s,array &$j):void {$fingerprint=hash('sha256',json_encode([$j['audioSha256'],$j['selection']['start'],$j['selection']['end'],$j['settings']['mode'],$j['settings']['formats'],$j['cast'],$j['settings']['channelId'],$j['sourceRevision']]));foreach($s['jobs'] as $other)if($other['id']!==$j['id']&&($other['fingerprint']??'')===$fingerprint&&$other['state']!=='cancelled')throw new DomainException('duplicate_production');$j['fingerprint']=$fingerprint;}
